    INSERT INTO "__SCHEMA__".content_version
      (content_version_id, kind, family, source_path, review_status, rights_status, content_sha256, exam_id)
    VALUES
    ('telc-deutsch-b1.writing-guide@v1', 'guide', 'writing-guide', 'data/writing-guide.json', 'unreviewed', 'unknown', 'dedcabdb965950232a6001c365658251d22183e1aefbc5db11739f63c0db842d', 'telc-deutsch-b1'),
    ('telc-deutsch-b1.speaking-guide@v1', 'guide', 'speaking-guide', 'data/speaking-guide.json', 'unreviewed', 'unknown', '941ce2745c628277ed2ed216f12542d482c12ad70c72a4e910f81ca7b2c0d767', 'telc-deutsch-b1')
    INSERT INTO "__SCHEMA__".guide
      (guide_id, exam_id, family, title, intro, intro_en, watch_out, watch_out_en, section_count, content_version_id)
    VALUES
    ('writing-guide', 'telc-deutsch-b1', 'writing-guide', 'Briefe schreiben', NULL, NULL, '["Die Anrede fehlt oder passt nicht zum Empfänger. Formell passt Sehr geehrte Frau Berger, privat zum Beispiel Liebe Julia.","Sie und du werden gemischt, zum Beispiel Sehr geehrte Frau Berger, wie geht es dir?","Ein Leitpunkt fehlt oder wird nur mit einem Stichwort behandelt.","Der Text ist viel zu lang oder viel zu kurz, zum Beispiel nur 40 Wörter.","Die Grußformel passt nicht zum Ton, zum Beispiel Tschüss in einem formellen Brief.","Die Verbform oder die Wortstellung ist falsch, zum Beispiel Ich habe den Kurs bezahlt gehabt."]', '["The salutation is missing or does not suit the recipient. Sehr geehrte Frau Berger works formally; Liebe Julia works for a personal letter.","Sie and du are mixed, for example Sehr geehrte Frau Berger, wie geht es dir?","A guiding point is missing or dealt with using only a single keyword.","The text is far too long or far too short, for example only 40 words.","The sign-off does not match the tone, for example Tschüss in a formal letter.","The verb form or the word order is wrong, for example Ich habe den Kurs bezahlt gehabt."]', 19, 'telc-deutsch-b1.writing-guide@v1'),
    ('speaking-guide', 'telc-deutsch-b1', 'speaking-guide', 'Mündliche Prüfung', NULL, NULL, '[]', '[]', 3, 'telc-deutsch-b1.speaking-guide@v1')
    INSERT INTO "__SCHEMA__".guide_section
      (guide_id, section_id, ordinal, kind, title, title_en, summary, summary_en, payload)
    VALUES
    ('writing-guide', 'telc-deutsch-b1.writing-guide.step-1', 0, 'step', 'Die Aufgabe verstehen', 'Understanding the task', 'Wer die Situation nicht richtig liest, schreibt am Thema vorbei und verliert schon am Anfang wichtige Punkte.', 'Anyone who does not read the situation properly writes off-topic and loses important marks right at the start.', '{"points":[{"idea":"Wer schreibt an wen?","ideaEn":"Who is writing to whom?","detail":"Prüfen Sie zuerst, wer der Absender und wer der Empfänger ist. Davon hängen Anrede, Ton und Inhalt ab. Ein Brief an eine Firma klingt ganz anders als eine Nachricht an eine Freundin.","detailEn":"First check who the sender is and who the recipient is. The salutation, the tone and the content all depend on this. A letter to a company sounds completely different from a message to a friend.","good":"An eine Firma: Sehr geehrte Damen und Herren, / An eine Freundin: Liebe Julia,","bad":"An eine Firma: Hey Leute,"},{"idea":"Warum schreibe ich?","ideaEn":"Why am I writing?","detail":"Suchen Sie den Anlass in der Aufgabe. Jede Aufgabe hat einen klaren Grund: eine Beschwerde, eine Anfrage, eine Absage oder eine Einladung. Dieser Grund gehört in die Einleitung.","detailEn":"Find the reason in the task. Every task has a clear reason: a complaint, an enquiry, a cancellation or an invitation. That reason belongs in the introduction."},{"idea":"Formell oder privat?","ideaEn":"Formal or personal?","detail":"Achten Sie auf die Beziehung zwischen den Personen. Bei Fremden, Firmen und Behörden schreiben Sie formell mit Sie. Bei Freunden und Familie schreiben Sie privat mit du.","detailEn":"Look at the relationship between the people. With strangers, companies and authorities you write formally with Sie. With friends and family you write personally with du.","good":"Formell: Könnten Sie mir bitte helfen? / Privat: Kannst du mir bitte helfen?","bad":"Kannst Sie mir bitte helfen?"},{"idea":"Welche Rolle habe ich?","ideaEn":"What role am I playing?","detail":"Sie schreiben nicht als Sie selbst, sondern als die Person in der Aufgabe. Erfinden Sie keine neuen Namen und keine neuen Fakten, sondern bleiben Sie genau bei der Situation.","detailEn":"You are not writing as yourself but as the person in the task. Do not invent new names or new facts — stick exactly to the situation."}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.step-2', 1, 'step', 'Die vier Leitpunkte', 'The four guiding points', 'Die vier Leitpunkte sind das Gerüst der ganzen Aufgabe und bringen die meisten Punkte.', 'The four guiding points are the skeleton of the whole task and they earn the most marks.', '{"points":[{"idea":"Alle vier Leitpunkte müssen vorkommen","ideaEn":"All four guiding points must appear","detail":"Jeder Leitpunkt ist ein eigener Inhaltspunkt. Wenn einer fehlt, fehlt ein Viertel des geforderten Inhalts und die Bewertung fällt schlechter aus.","detailEn":"Each guiding point is a separate content point. If one is missing, a quarter of the required content is missing and the assessment suffers.","good":"Ich habe alle vier Punkte in je einem Absatz behandelt.","bad":"Ich habe nur über den Grund geschrieben."},{"idea":"Reihenfolge einhalten","ideaEn":"Keep to the order","detail":"Bearbeiten Sie die Leitpunkte in der Reihenfolge der Aufgabe. So findet der Bewerter alles schnell und der Text wirkt klar geordnet.","detailEn":"Work through the guiding points in the order given in the task. That way the marker finds everything quickly and the text looks clearly organised."},{"idea":"Jeden Leitpunkt deutlich machen","ideaEn":"Make each guiding point clear","detail":"Schreiben Sie zu jedem Leitpunkt mindestens einen ganzen Satz. Ein halber Satz oder nur ein Stichwort reicht nicht aus.","detailEn":"Write at least one full sentence for each guiding point. Half a sentence or a single keyword is not enough.","good":"Außerdem möchte ich wissen, wie viel der Kurs kostet.","bad":"Preis?"},{"idea":"Nichts dazu erfinden","ideaEn":"Do not invent anything extra","detail":"Sie brauchen keine zusätzlichen Inhalte. Zwei oder drei gute Sätze pro Leitpunkt sind genug, denn ein langer Text bringt keine Extrapunkte.","detailEn":"You do not need extra content. Two or three good sentences per guiding point are enough, because a long text earns no extra marks."}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.step-3', 2, 'step', 'Aufbau des Briefes', 'Structure of the letter', 'Ein klarer Aufbau mit Anrede, Einleitung, Hauptteil, Schluss und Grußformel wirkt sofort sicher und gut.', 'A clear structure with salutation, introduction, main part, closing and sign-off immediately looks confident and good.', '{"points":[{"idea":"Anrede","ideaEn":"Salutation","detail":"Beginnen Sie mit der Anrede und setzen Sie danach ein Komma. In der nächsten Zeile schreiben Sie klein weiter, wenn Sie formell schreiben.","detailEn":"Start with the salutation and put a comma after it. On the next line you continue in lower case if you are writing formally.","good":"Sehr geehrte Frau Berger,","bad":"Sehr geehrte Frau Berger"},{"idea":"Einleitung","ideaEn":"Introduction","detail":"Schreiben Sie ein bis zwei Sätze zum Anlass. Nennen Sie den Grund, warum Sie schreiben, damit der Leser sofort versteht, worum es geht.","detailEn":"Write one or two sentences about the occasion. Name the reason why you are writing so the reader understands immediately what it is about.","good":"ich schreibe Ihnen, weil ich ein Problem mit meiner Bestellung habe."},{"idea":"Hauptteil","ideaEn":"Main part","detail":"Der Hauptteil enthält die vier Leitpunkte. Jeder Leitpunkt bekommt einen eigenen kleinen Absatz mit zwei bis drei Sätzen.","detailEn":"The main part contains the four guiding points. Each guiding point gets its own short paragraph of two to three sentences."},{"idea":"Schluss und Grußformel","ideaEn":"Closing and sign-off","detail":"Beenden Sie den Brief mit einem Satz, zum Beispiel einer Bitte um Antwort. Danach folgen die zum Empfänger passende Grußformel und Ihr Name in einer neuen Zeile. Privat passen zum Beispiel Liebe Grüße oder Bis bald.","detailEn":"End the letter with one sentence, for example a request for a reply. Then a sign-off suited to the recipient and your name follow on a new line. For a personal letter, Liebe Grüße or Bis bald work well.","good":"An eine Freundin: Liebe Grüße\nAnna","bad":"An eine Firma: Tschüss\nAnna"}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.step-4', 3, 'step', 'Anrede und Grußformel', 'Salutation and sign-off', 'Anrede und Grußformel rahmen den Brief und zeigen dem Bewerter sofort, ob der Ton stimmt.', 'The salutation and the sign-off frame the letter and show the marker immediately whether the tone is right.', '{"points":[{"idea":"Sie oder du?","ideaEn":"Sie or du?","detail":"Bei fremden Personen, Firmen und Ämtern schreiben Sie immer Sie. Bei Freunden, Familie und guten Bekannten schreiben Sie du. Mischen Sie die beiden Formen nie in einem Brief.","detailEn":"With strangers, companies and authorities always write Sie. With friends, family and close acquaintances write du. Never mix the two forms in one letter.","good":"Könnten Sie mir bitte antworten?","bad":"Könnten Sie mir bitte antworten? Wie geht es dir?"},{"idea":"Empfänger mit Namen","ideaEn":"Recipient with a name","detail":"Wenn der Name in der Aufgabe steht, schreiben Sie ihn in die Anrede. Formell nehmen Sie Frau oder Herr mit dem Nachnamen. Privat verwenden Sie den Vornamen, zum Beispiel Liebe Julia oder Lieber Max.","detailEn":"If the name is given in the task, use it in the salutation. For formal letters, use Frau or Herr with the surname. For personal letters, use the first name, for example Liebe Julia or Lieber Max.","good":"Sehr geehrter Herr Weber,","bad":"Sehr geehrte Herr Weber,"},{"idea":"Empfänger ohne Namen","ideaEn":"Recipient without a name","detail":"Wenn Sie den Namen nicht kennen, schreiben Sie die allgemeine Form. Diese Anrede passt bei Firmen, Schulen und Behörden.","detailEn":"If you do not know the name, use the general form. This salutation suits companies, schools and authorities.","good":"Sehr geehrte Damen und Herren,","bad":"Sehr geehrte Frau,"},{"idea":"Passende Grußformel","ideaEn":"A fitting sign-off","detail":"Die Grußformel muss zum Ton passen. Formell nehmen Sie Mit freundlichen Grüßen, privat Liebe Grüße oder Viele Grüße. Danach schreiben Sie Ihren Namen ohne Komma.","detailEn":"The sign-off has to match the tone. Use Mit freundlichen Grüßen for formal letters, Liebe Grüße or Viele Grüße for personal ones. After it you write your name without a comma.","good":"Mit freundlichen Grüßen\nMehmet Yilmaz","bad":"Mit freundlichen Grüßen\nLiebe Julia"}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.step-5', 4, 'step', 'Umfang und Zeit', 'Length and time', 'Wer den Umfang und die Zeit richtig plant, schreibt ruhig, vollständig und ohne Stress.', 'Anyone who plans the length and the time properly writes calmly, completely and without stress.', '{"points":[{"idea":"80 bis 120 Wörter","ideaEn":"80 to 120 words","detail":"Die Aufgabe verlangt etwa 80 bis 120 Wörter. In dieser Länge passen alle vier Leitpunkte gut hinein. Zu kurze Texte wirken unvollständig, zu lange Texte bringen keine Extrapunkte.","detailEn":"The task asks for about 80 to 120 words. All four guiding points fit comfortably into that length. Texts that are too short look incomplete, and texts that are too long earn no extra marks.","good":"Ich schreibe zu jedem Leitpunkt zwei bis drei Sätze.","bad":"Ich schreibe fünf Seiten, damit es besser aussieht."},{"idea":"Zeit einteilen","ideaEn":"Divide up the time","detail":"Sie haben 30 Minuten. Planen Sie etwa 5 Minuten für das Lesen und Planen, 20 Minuten für das Schreiben und 5 Minuten für die Kontrolle.","detailEn":"You have 30 minutes. Plan about 5 minutes for reading and planning, 20 minutes for writing and 5 minutes for checking.","good":"Erst planen, dann schreiben, dann prüfen."},{"idea":"Nicht zu viel schreiben","ideaEn":"Do not write too much","detail":"Mehr Wörter bedeuten mehr Fehler. Je länger der Text, desto größer ist die Gefahr, dass Sie die Zeit verlieren und wichtige Punkte vergessen.","detailEn":"More words mean more mistakes. The longer the text, the greater the risk that you run out of time and forget important points.","good":"Ich bleibe bei einem klaren und kurzen Text.","bad":"Ich schreibe alles auf, was mir einfällt."},{"idea":"Am Ende kontrollieren","ideaEn":"Check at the end","detail":"Lesen Sie den Text am Ende noch einmal. Prüfen Sie die Verbform, die Großschreibung der Nomen und die Anrede. Kleine Fehler kosten schnell Punkte.","detailEn":"Read the text through once more at the end. Check the verb forms, the capitalisation of nouns and the salutation. Small mistakes quickly cost marks."}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.step-6', 5, 'step', 'Worauf die Bewerter achten', 'What the markers look for', 'Die Bewertung folgt festen Kriterien, und wer sie kennt, kann gezielt Punkte sammeln.', 'The assessment follows fixed criteria, and anyone who knows them can collect marks deliberately.', '{"points":[{"idea":"Aufgabengerechtheit","ideaEn":"Task fulfilment","detail":"Der Bewerter prüft, ob alle vier Leitpunkte klar und richtig behandelt sind. Fehlende oder falsch verstandene Punkte kosten hier viele Punkte.","detailEn":"The marker checks whether all four guiding points are dealt with clearly and correctly. Missing or misunderstood points cost a lot of marks here."},{"idea":"Kommunikative Gestaltung","ideaEn":"Communicative design","detail":"Der Text muss zum Anlass und zum Empfänger passen. Eine Beschwerde klingt anders als eine Einladung, und höfliche Formeln gehören einfach dazu.","detailEn":"The text has to suit the occasion and the recipient. A complaint sounds different from an invitation, and polite formulas are simply part of it.","good":"Könnten Sie mir bitte bis Freitag antworten?","bad":"Antworten Sie sofort!"},{"idea":"Formale Richtigkeit","ideaEn":"Formal accuracy","detail":"Achten Sie auf Grammatik, Wortstellung, Verbformen und Rechtschreibung. Auch die Anrede, die Grußformel und die Absätze gehören dazu.","detailEn":"Pay attention to grammar, word order, verb forms and spelling. The salutation, the sign-off and the paragraphs count too.","good":"Ich habe den Kurs schon bezahlt.","bad":"Ich habe den Kurs schon bezahlt gehabt."},{"idea":"Ausdruck","ideaEn":"Expression","detail":"Benutzen Sie Wörter, die Sie sicher kennen. Einfache Sätze mit Verbindungswörtern wie weil, deshalb und außerdem wirken besser als komplizierte Sätze mit Fehlern.","detailEn":"Use words you know reliably. Simple sentences with connectors such as weil, deshalb and außerdem work better than complicated sentences with mistakes.","good":"Deshalb bitte ich Sie um eine schnelle Antwort.","bad":"Ich erbitte umgehendst Ihre geschätzte Rückäußerung."}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.phrases-1', 6, 'phrase_group', 'Anrede', 'Salutation', 'Diese Bausteine stehen ganz am Anfang des Briefes, direkt vor dem ersten Satz.', 'These building blocks come right at the start of the letter, directly before the first sentence.', '{"items":[{"de":"Sehr geehrte Damen und Herren,","en":"Dear Sir or Madam,","example":"Sehr geehrte Damen und Herren, ich schreibe Ihnen wegen Ihrer Anzeige."},{"de":"Sehr geehrte Frau ...,","en":"Dear Ms ...,","example":"Sehr geehrte Frau Berger, ich habe eine Frage zu meiner Bestellung."},{"de":"Sehr geehrter Herr ...,","en":"Dear Mr ...,","example":"Sehr geehrter Herr Weber, leider muss ich unseren Termin verschieben."},{"de":"Liebe Frau ...,","en":"Dear Ms ... (friendly)","example":"Liebe Frau Berger, vielen Dank für Ihre nette Hilfe."},{"de":"Hallo ...,","en":"Hello ... (informal)","example":"Hallo Julia, wie geht es dir und deiner Familie?"},{"de":"Liebe ..., / Lieber ...,","en":"Dear ... (informal)","example":"Liebe Julia, ich habe mich sehr über deine Nachricht gefreut."}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.phrases-2', 7, 'phrase_group', 'Einleitung und Anlass', 'Introduction and occasion', 'Mit diesen Sätzen erklären Sie gleich am Anfang, warum Sie schreiben.', 'With these sentences you explain right at the start why you are writing.', '{"items":[{"de":"ich schreibe Ihnen, weil ...","en":"I am writing to you because ...","example":"ich schreibe Ihnen, weil ich mich für Ihren Kurs interessiere."},{"de":"ich wende mich an Sie, weil ...","en":"I am contacting you because ...","example":"ich wende mich an Sie, weil ich ein Problem mit Ihrer Rechnung habe."},{"de":"vielen Dank für Ihre E-Mail vom ...","en":"many thanks for your e-mail of ...","example":"vielen Dank für Ihre E-Mail vom 5. Mai, die ich heute bekommen habe."},{"de":"ich habe Ihre Anzeige im Internet gelesen.","en":"I read your advertisement on the internet.","example":"ich habe Ihre Anzeige im Internet gelesen und interessiere mich sehr dafür."},{"de":"leider muss ich Ihnen etwas Unangenehmes mitteilen.","en":"Unfortunately I have to tell you something unpleasant.","example":"leider muss ich Ihnen etwas Unangenehmes mitteilen: Ich kann am Freitag nicht kommen."},{"de":"ich habe eine Frage zu ...","en":"I have a question about ...","example":"ich habe eine Frage zu dem Deutschkurs im August."}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.phrases-3', 8, 'phrase_group', 'Grund nennen', 'Giving a reason', 'Mit diesen Bausteinen begründen Sie Ihr Anliegen höflich und klar.', 'With these building blocks you justify your request politely and clearly.', '{"items":[{"de":"deshalb ...","en":"that is why ...","example":"Deshalb bitte ich Sie um eine schnelle Antwort."},{"de":"weil ...","en":"because ...","example":"Ich kann am Freitag nicht kommen, weil meine Mutter krank ist."},{"de":"der Grund dafür ist, dass ...","en":"the reason for that is that ...","example":"Der Grund dafür ist, dass ich an diesem Tag arbeiten muss."},{"de":"leider ist es so, dass ...","en":"unfortunately it is the case that ...","example":"Leider ist es so, dass das Gerät schon nach zwei Tagen kaputt war."},{"de":"ich habe schon versucht, ... zu ...","en":"I have already tried to ...","example":"Ich habe schon versucht, Sie telefonisch zu erreichen, aber niemand hat geantwortet."}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.phrases-4', 9, 'phrase_group', 'Bitten und Fragen', 'Requests and questions', 'Diese Sätze brauchen Sie, wenn Sie etwas möchten oder eine Information wollen.', 'You need these sentences when you want something or want information.', '{"items":[{"de":"Könnten Sie mir bitte ... ?","en":"Could you please ... ?","example":"Könnten Sie mir bitte den Preis für den Kurs nennen?"},{"de":"ich möchte Sie bitten, ... zu ...","en":"I would like to ask you to ...","example":"ich möchte Sie bitten, mir ein neues Gerät zu schicken."},{"de":"ich würde mich freuen, wenn ...","en":"I would be pleased if ...","example":"ich würde mich freuen, wenn Sie mir bald antworten könnten."},{"de":"wäre es möglich, dass ... ?","en":"would it be possible that ... ?","example":"Wäre es möglich, dass wir den Termin auf Montag verschieben?"},{"de":"ich hätte noch eine Frage:","en":"I would have one more question:","example":"Ich hätte noch eine Frage: Wie lange dauert der Kurs?"},{"de":"Bitte sagen Sie mir, ob ...","en":"Please tell me whether ...","example":"Bitte sagen Sie mir, ob noch ein Platz frei ist."}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.phrases-5', 10, 'phrase_group', 'Entschuldigung', 'Apology', 'Mit diesen Formeln entschuldigen Sie sich höflich, wenn etwas schiefgeht.', 'With these formulas you apologise politely when something goes wrong.', '{"items":[{"de":"es tut mir sehr leid, aber ...","en":"I am very sorry, but ...","example":"Es tut mir sehr leid, aber ich muss den Termin absagen."},{"de":"ich möchte mich bei Ihnen entschuldigen.","en":"I would like to apologize to you.","example":"Ich möchte mich bei Ihnen für die Verspätung entschuldigen."},{"de":"bitte entschuldigen Sie die Umstände.","en":"please excuse the inconvenience.","example":"Bitte entschuldigen Sie die Umstände, die dadurch entstanden sind."},{"de":"ich hoffe, Sie haben Verständnis dafür.","en":"I hope you understand.","example":"Ich hoffe, Sie haben Verständnis dafür, dass ich so kurzfristig absagen muss."},{"de":"das war keine Absicht.","en":"that was not intentional.","example":"Das war keine Absicht, und es kommt auch nicht wieder vor."}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.phrases-6', 11, 'phrase_group', 'Dank', 'Thanks', 'Danken Sie höflich, wenn Sie eine Information, Hilfe oder eine Einladung bekommen haben.', 'Thank someone politely when you have received information, help or an invitation.', '{"items":[{"de":"vielen Dank für ...","en":"many thanks for ...","example":"Vielen Dank für Ihre schnelle Antwort und Ihre Hilfe."},{"de":"ich bedanke mich bei Ihnen für ...","en":"I thank you for ...","example":"Ich bedanke mich bei Ihnen für die freundliche Beratung."},{"de":"vielen Dank im Voraus.","en":"many thanks in advance.","example":"Vielen Dank im Voraus für Ihre Mühe."},{"de":"das ist sehr nett von Ihnen.","en":"that is very kind of you.","example":"Das ist sehr nett von Ihnen, dass Sie mir so schnell geholfen haben."},{"de":"ich freue mich sehr über ...","en":"I am very pleased about ...","example":"Ich freue mich sehr über Ihre Einladung zu Ihrem Fest."}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.phrases-7', 12, 'phrase_group', 'Vorschlag und Meinung', 'Suggestion and opinion', 'Mit diesen Bausteinen machen Sie einen Vorschlag oder sagen höflich Ihre Meinung.', 'With these building blocks you make a suggestion or give your opinion politely.', '{"items":[{"de":"wie wäre es, wenn ... ?","en":"how about it if ... ?","example":"Wie wäre es, wenn wir uns am Montag treffen?"},{"de":"ich schlage vor, dass ...","en":"I suggest that ...","example":"Ich schlage vor, dass wir den Termin auf Freitag legen."},{"de":"meiner Meinung nach ...","en":"in my opinion ...","example":"Meiner Meinung nach ist der Preis für den Kurs zu hoch."},{"de":"vielleicht könnten wir ...","en":"perhaps we could ...","example":"Vielleicht könnten wir das Problem gemeinsam lösen."},{"de":"ich finde es besser, wenn ...","en":"I think it is better if ...","example":"Ich finde es besser, wenn wir nächste Woche noch einmal sprechen."}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.phrases-8', 13, 'phrase_group', 'Schluss und Grußformel', 'Closing and sign-off', 'Diese Bausteine stehen am Ende des Briefes, nach dem letzten Inhaltssatz.', 'These building blocks come at the end of the letter, after the last content sentence.', '{"items":[{"de":"ich freue mich auf Ihre Antwort.","en":"I look forward to your reply.","example":"Ich freue mich auf Ihre Antwort und bedanke mich noch einmal."},{"de":"bitte antworten Sie mir bis ...","en":"please reply to me by ...","example":"Bitte antworten Sie mir bis zum 20. Juni, damit ich planen kann."},{"de":"für weitere Fragen stehe ich Ihnen gerne zur Verfügung.","en":"I am happy to help with further questions.","example":"Für weitere Fragen stehe ich Ihnen gerne zur Verfügung."},{"de":"Mit freundlichen Grüßen","en":"Yours sincerely","example":"Mit freundlichen Grüßen, Anna Keller"},{"de":"Liebe Grüße","en":"Kind regards (informal)","example":"Liebe Grüße und bis Samstag, deine Tanja"},{"de":"Bis bald / Alles Liebe","en":"See you soon / All the best (informal)","example":"Bis bald, ich freue mich schon sehr auf dich."}]}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.letter-1', 14, 'example_letter', 'Beschwerde', 'Complaint', 'Frau Keller schreibt an eine Verkäuferin, weil der neue Kaffeeautomat schon nach zwei Tagen nicht mehr funktioniert.', 'Ms Keller writes to a sales assistant because the new coffee machine stopped working after only two days.', '{"leitpunkte":["Grund der Beschwerde: Was ist passiert?","Was Sie schon versucht haben","Was Sie jetzt erwarten (neues Gerät oder Geld zurück)","Bis wann Sie eine Antwort brauchen"],"leitpunkteEn":["Reason for the complaint: what happened?","What you have already tried","What you now expect (a new device or your money back)","When you need a reply by"],"text":"Sehr geehrte Frau Berger,\n\nich schreibe Ihnen, weil ich mit dem Kaffeeautomaten, den ich am 3. Mai bei Ihnen gekauft habe, sehr unzufrieden bin. Das Gerät ist schon nach zwei Tagen kaputtgegangen.\n\nIch habe die Bedienungsanleitung genau gelesen und den Automaten mehrmals neu gestartet, aber er funktioniert immer noch nicht. Deshalb habe ich am Montag bei Ihrer Hotline angerufen. Leider hat mir dort niemand geholfen. Auch eine E-Mail an Ihren Kundenservice hat nichts gebracht.\n\nIch möchte Sie deshalb bitten, mir ein neues Gerät zu schicken oder mir den Kaufpreis zurückzuzahlen. Bitte antworten Sie mir bis zum 20. Juni.\n\nMit freundlichen Grüßen\nAnna Keller"}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.letter-2', 15, 'example_letter', 'Anfrage', 'Enquiry', 'Herr Yilmaz schreibt an eine Sprachschule, weil er im August einen Deutschkurs machen möchte und noch Fragen hat.', 'Mr Yilmaz writes to a language school because he wants to take a German course in August and still has some questions.', '{"leitpunkte":["Warum ich schreibe: Interesse am Intensivkurs im August","Fragen zu Preis und Stundenzahl","Fragen zu Unterkunft und Einstufungstest","Bitte um eine schnelle Antwort"],"leitpunkteEn":["Why I am writing: interest in the intensive course in August","Questions about the price and the number of hours","Questions about accommodation and the placement test","Request for a quick reply"],"text":"Sehr geehrte Damen und Herren,\n\nich habe Ihre Anzeige im Internet gelesen und interessiere mich sehr für Ihren Intensivkurs Deutsch im August.\n\nLeider finde ich auf Ihrer Webseite nicht alle Informationen. Deshalb habe ich einige Fragen: Wie viel kostet der Kurs und wie viele Stunden hat er pro Woche? Können Sie mir auch ein Zimmer bei einer Gastfamilie vermitteln? Außerdem möchte ich wissen, ob ich vor dem Kurs einen Einstufungstest machen muss.\n\nIch würde mich sehr freuen, wenn Sie mir diese Fragen bald beantworten könnten. Vielen Dank im Voraus.\n\nMit freundlichen Grüßen\nMehmet Yilmaz"}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.letter-3', 16, 'example_letter', 'Absage', 'Cancellation', 'Frau Nowak schreibt an ihren Arzt, weil sie einen Termin nicht wahrnehmen kann und einen neuen Termin braucht.', 'Ms Nowak writes to her doctor because she cannot attend an appointment and needs a new one.', '{"leitpunkte":["Termin absagen: welcher Termin genau","Grund nennen und sich entschuldigen","Neuen Termin vorschlagen","Um Bestätigung bitten"],"leitpunkteEn":["Cancel the appointment: which one exactly","Give the reason and apologise","Suggest a new appointment","Ask for confirmation"],"text":"Sehr geehrter Herr Doktor Weber,\n\nleider muss ich unseren Termin am Donnerstag, dem 12. September, absagen. Ich habe mich sehr darauf gefreut, aber es geht nicht anders.\n\nMeine Mutter ist plötzlich krank geworden und ich muss sie ins Krankenhaus bringen. Das tut mir wirklich sehr leid. Ich hoffe, Sie haben dafür Verständnis.\n\nKönnten wir den Termin vielleicht auf den 19. September verschieben? Am Nachmittag habe ich immer Zeit. Bitte schreiben Sie mir kurz, ob Ihnen dieser Termin passt.\n\nIch melde mich nächste Woche wieder bei Ihnen. Vielen Dank für Ihr Verständnis.\n\nMit freundlichen Grüßen\nSara Nowak"}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.letter-4', 17, 'example_letter', 'Einladung', 'Invitation', 'Tanja schreibt an ihre Freundin Julia und antwortet auf die Einladung zur Geburtstagsparty.', 'Tanja writes to her friend Julia and replies to the invitation to the birthday party.', '{"leitpunkte":["Dank für die Einladung und Zusage","Was ich mitbringe","Nach der Uhrzeit fragen","Nach dem Weg fragen"],"leitpunkteEn":["Thanks for the invitation and accepting","What I will bring","Ask about the time","Ask for directions"],"text":"Liebe Julia,\n\nvielen Dank für deine Einladung zu deiner Geburtstagsparty am Samstag! Ich habe mich sehr darüber gefreut und komme natürlich sehr gern.\n\nIch habe schon eine Idee für ein Geschenk. Außerdem kann ich einen Salat und einen Kuchen mitbringen, wenn du möchtest. Sag mir einfach, was du noch brauchst.\n\nEine Frage habe ich aber: Wann fängt die Party an und wie komme ich am besten zu dir? Ich kenne deine neue Wohnung noch nicht. Kannst du mir bitte den Weg beschreiben?\n\nIch freue mich schon sehr auf Samstag!\n\nLiebe Grüße\nTanja"}'::jsonb),
    ('writing-guide', 'telc-deutsch-b1.writing-guide.checklist', 18, 'checklist', 'Checkliste', 'Checklist', 'Vor dem Abgeben durchgehen.', 'Work through this before submitting.', '{"items":["Ich habe alle vier Leitpunkte klar und in der richtigen Reihenfolge behandelt.","Meine Anrede passt zum Empfänger, und die Grußformel passt zur Anrede.","Ich benutze in dem ganzen Brief nur eine Form: Sie oder du.","Mein Text hat etwa 80 bis 120 Wörter.","Ich habe den Brief in Absätze gegliedert und zu jedem Leitpunkt etwas geschrieben.","Ich habe am Ende die Verbformen, die Großschreibung der Nomen und die Satzzeichen kontrolliert.","Ich habe passende freundliche Formeln wie Könnten Sie, Kannst du bitte oder ich würde mich freuen benutzt.","Mein Name steht unter der Grußformel, und ich habe keinen neuen Inhalt erfunden."],"itemsEn":["I have dealt with all four guiding points clearly and in the right order.","My salutation suits the recipient and the sign-off suits the salutation.","I use only one form throughout the letter: Sie or du.","My text is about 80 to 120 words.","I have divided the letter into paragraphs and written something for each guiding point.","At the end I checked the verb forms, the capitalisation of nouns and the punctuation.","I used friendly formulas suited to the recipient, such as Könnten Sie, Kannst du bitte or ich würde mich freuen.","My name is below the sign-off and I did not invent any new content."]}'::jsonb),
    ('speaking-guide', 'telc-deutsch-b1.speaking-guide.sp1', 0, 'part', 'Teil 1 – Präsentation', 'Part 1 – Presentation', 'Der Kandidat präsentiert etwa drei Minuten lang ein Thema anhand von vier bis sechs Stichwörtern auf der Aufgabenkarte und beantwortet danach eine Anschlussfrage.', 'The candidate presents a topic for about three minutes using the four to six keywords on the task card, and then answers one follow-up question.', '{"minutes":3,"approach":[{"step":"Begrüßen und Thema nennen","detail":"Ein bis zwei Sätze. Nennen Sie das Thema klar und deutlich, damit die Prüfer sofort wissen, worüber Sie sprechen.","seconds":20,"stepEn":"Greet the examiners and name the topic","detailEn":"One or two sentences. Name the topic clearly so the examiners know straight away what you are talking about."},{"step":"Überblick über die Stichwörter geben","detail":"Sagen Sie kurz, welche Punkte Sie nennen werden. So bekommen Ihre Ausführungen eine klare Struktur.","seconds":20,"stepEn":"Give an overview of the keywords","detailEn":"Say briefly which points you are going to mention. That gives your presentation a clear structure."},{"step":"Die Stichwörter der Reihe nach bearbeiten","detail":"Machen Sie aus jedem Stichwort zwei bis drei ganze Sätze. Verbinden Sie die Punkte mit Wörtern wie zuerst, danach und zum Schluss.","seconds":70,"stepEn":"Work through the keywords one by one","detailEn":"Turn each keyword into two or three full sentences. Link the points with words such as zuerst, danach and zum Schluss."},{"step":"Eigene Meinung und Erfahrung einbringen","detail":"Berichten Sie kurz von sich selbst: Was haben Sie erlebt? Was finden Sie gut oder schlecht? Das wirkt natürlich und persönlich.","seconds":35,"stepEn":"Add your own opinion and experience","detailEn":"Say something about yourself: what have you experienced? What do you think is good or bad? That sounds natural and personal."},{"step":"Zusammenfassen","detail":"Fassen Sie Ihren wichtigsten Gedanken in ein bis zwei Sätzen zusammen und bedanken Sie sich für das Zuhören.","seconds":20,"stepEn":"Summarise","detailEn":"Sum up your most important thought in one or two sentences and thank the listeners."},{"step":"Zu Anschlussfragen einladen","detail":"Bieten Sie am Ende an, Fragen zu beantworten. So zeigen Sie, dass Sie das Gespräch führen können.","seconds":15,"stepEn":"Invite follow-up questions","detailEn":"Offer to answer questions at the end. That shows you can lead the conversation."}],"phrases":[{"group":"Einleitung","hint":"Mit diesen Sätzen beginnen Sie die Präsentation und nennen das Thema.","items":[{"de":"Ich möchte Ihnen ... vorstellen.","en":"I would like to present ... to you.","example":"Ich möchte Ihnen meine Heimatstadt vorstellen."},{"de":"Mein Thema heute ist ...","en":"My topic today is ...","example":"Mein Thema heute ist mein Beruf als Krankenpfleger."},{"de":"Ich möchte heute über ... sprechen.","en":"Today I would like to talk about ...","example":"Ich möchte heute über meinen Lieblingssport sprechen."},{"de":"Wie Sie vielleicht wissen, ...","en":"As you may know, ...","example":"Wie Sie vielleicht wissen, wohne ich erst seit zwei Jahren in Deutschland."},{"de":"Ich habe mir das Thema ... ausgesucht, weil ...","en":"I chose the topic ... because ...","example":"Ich habe mir das Thema Feste in meinem Land ausgesucht, weil Feiern bei uns sehr wichtig sind."},{"de":"Zuerst möchte ich kurz sagen, worum es geht.","en":"First I would like to say briefly what this is about.","example":"Zuerst möchte ich kurz sagen, worum es geht: um meine Arbeit in einem kleinen Büro."}],"groupEn":"Introduction","hintEn":"With these sentences you begin the presentation and name the topic."},{"group":"Struktur und Reihenfolge","hint":"Diese Redemittel ordnen Ihre Präsentation und führen die Prüfer von Punkt zu Punkt.","items":[{"de":"Ich möchte über drei Punkte sprechen: ...","en":"I would like to talk about three points: ...","example":"Ich möchte über drei Punkte sprechen: meine Stadt, die Menschen und das Leben dort."},{"de":"Zuerst ... danach ... und zum Schluss ...","en":"First ... then ... and finally ...","example":"Zuerst erzähle ich von meiner Familie, danach von meiner Arbeit und zum Schluss von meinen Plänen."},{"de":"Ein wichtiger Punkt ist auch ...","en":"Another important point is ...","example":"Ein wichtiger Punkt ist auch die Frage, wie viel ein Ausflug kosten darf."},{"de":"Ich beginne mit ... und komme danach zu ...","en":"I will start with ... and then move on to ...","example":"Ich beginne mit meiner Ausbildung und komme danach zu meinem jetzigen Job."},{"de":"Der nächste Punkt ist ...","en":"The next point is ...","example":"Der nächste Punkt ist das Essen in meinem Heimatland."},{"de":"Dazu möchte ich ein Beispiel geben.","en":"I would like to give an example of that.","example":"Dazu möchte ich ein Beispiel geben: Meine Schwester arbeitet auch im Supermarkt."}],"groupEn":"Structure and order","hintEn":"These phrases organise your presentation and guide the examiners from point to point."},{"group":"Vor- und Nachteile","hint":"Nutzen Sie diese Sätze, wenn Sie ein Stichwort von zwei Seiten beleuchten wollen.","items":[{"de":"Ein Vorteil ist, dass ...","en":"One advantage is that ...","example":"Ein Vorteil ist, dass man in der Stadt schnell mit dem Bus fahren kann."},{"de":"Ein Nachteil ist, dass ...","en":"One disadvantage is that ...","example":"Ein Nachteil ist, dass die Mieten in der Stadt sehr hoch sind."},{"de":"Positiv finde ich, dass ...","en":"I think it is positive that ...","example":"Positiv finde ich, dass es in meinem Beruf viele freundliche Kollegen gibt."},{"de":"Negativ finde ich, dass ...","en":"I think it is negative that ...","example":"Negativ finde ich, dass ich am Samstag fast immer arbeiten muss."},{"de":"Auf der einen Seite ..., auf der anderen Seite ...","en":"On the one hand ... on the other hand ...","example":"Auf der einen Seite ist das Leben auf dem Land ruhig, auf der anderen Seite gibt es dort wenig Arbeit."},{"de":"Man muss auch beachten, dass ...","en":"One also has to consider that ...","example":"Man muss auch beachten, dass ein Auto im Monat viel Geld kostet."}],"groupEn":"Advantages and disadvantages","hintEn":"Use these sentences when you want to look at a keyword from two sides."},{"group":"Eigene Erfahrung","hint":"Mit diesen Sätzen machen Sie die Präsentation persönlich und glaubwürdig.","items":[{"de":"Ich habe die Erfahrung gemacht, dass ...","en":"I have found that ...","example":"Ich habe die Erfahrung gemacht, dass man mit Geduld viel erreichen kann."},{"de":"Bei mir war es so, dass ...","en":"In my case it was like this: ...","example":"Bei mir war es so, dass ich nach dem Umzug zuerst keine Arbeit gefunden habe."},{"de":"Als ich ... war, habe ich ...","en":"When I was ..., I ...","example":"Als ich zwölf Jahre alt war, habe ich jeden Sommer bei meinem Onkel gearbeitet."},{"de":"Ich erinnere mich, dass ...","en":"I remember that ...","example":"Ich erinnere mich, dass wir als Kinder jeden Abend auf der Straße gespielt haben."},{"de":"In meinem Heimatland ist es üblich, dass ...","en":"In my home country it is common that ...","example":"In meinem Heimatland ist es üblich, dass die ganze Familie am Sonntag zusammen isst."},{"de":"Damit habe ich schon Erfahrungen gemacht.","en":"I already have experience with that.","example":"Mit dem Fahrrad zur Arbeit zu fahren ist bei uns normal, damit habe ich schon Erfahrungen gemacht."}],"groupEn":"Your own experience","hintEn":"With these sentences you make the presentation personal and credible."},{"group":"Zusammenfassung","hint":"Diese Sätze beenden Ihren Vortrag und heben den wichtigsten Gedanken hervor.","items":[{"de":"Zusammenfassend kann ich sagen, dass ...","en":"In summary, I can say that ...","example":"Zusammenfassend kann ich sagen, dass meine Heimatstadt für mich der schönste Ort ist."},{"de":"Zum Schluss möchte ich betonen, dass ...","en":"Finally I would like to emphasise that ...","example":"Zum Schluss möchte ich betonen, dass Gesundheit wichtiger ist als Geld."},{"de":"Alles in allem finde ich ...","en":"All in all, I find ...","example":"Alles in allem finde ich meinen Beruf sehr interessant."},{"de":"Ich fasse kurz zusammen: ...","en":"Let me summarise briefly: ...","example":"Ich fasse kurz zusammen: Der Job macht Spaß, aber die Arbeitszeiten sind schwierig."},{"de":"Deshalb ist ... für mich wichtig.","en":"That is why ... is important to me.","example":"Deshalb ist Zeit für meine Familie für mich wichtig."},{"de":"Ich hoffe, ich konnte Ihnen einen guten Überblick geben.","en":"I hope I was able to give you a good overview.","example":"Ich hoffe, ich konnte Ihnen einen guten Überblick über meinen Alltag geben."}],"groupEn":"Summary","hintEn":"These sentences end your talk and highlight the most important thought."},{"group":"Auf Anschlussfragen reagieren","hint":"Wenn die Prüfer nachfragen, bleiben Sie ruhig und antworten Sie in vollständigen Sätzen.","items":[{"de":"Das ist eine gute Frage. Ich denke, dass ...","en":"That is a good question. I think that ...","example":"Das ist eine gute Frage. Ich denke, dass sich in den nächsten Jahren viel ändern wird."},{"de":"Vielen Dank für die Frage. Also, ...","en":"Thank you for the question. Well, ...","example":"Vielen Dank für die Frage. Also, ich würde am liebsten in meiner Heimatstadt bleiben."},{"de":"Da bin ich mir nicht ganz sicher, aber ich glaube, dass ...","en":"I am not quite sure, but I believe that ...","example":"Da bin ich mir nicht ganz sicher, aber ich glaube, dass mehr Busse helfen würden."},{"de":"Könnten Sie die Frage bitte wiederholen?","en":"Could you please repeat the question?","example":"Entschuldigung, könnten Sie die Frage bitte wiederholen?"},{"de":"Ich habe noch nie darüber nachgedacht. Ich würde sagen, dass ...","en":"I have never thought about that. I would say that ...","example":"Ich habe noch nie darüber nachgedacht. Ich würde sagen, dass beide Wege möglich sind."},{"de":"Wie ich schon gesagt habe, ...","en":"As I already said, ...","example":"Wie ich schon gesagt habe, ist mir die Familie am wichtigsten."}],"groupEn":"Reacting to follow-up questions","hintEn":"If the examiners ask questions, stay calm and answer in full sentences."}],"examples":[{"topic":"Meine Heimatstadt","text":"Ich möchte Ihnen meine Heimatstadt vorstellen. Sie heißt Valjevo und liegt im Westen von Serbien. Dort habe ich meine ganze Kindheit verbracht, und meine Eltern wohnen noch heute dort. Ich möchte über drei Punkte sprechen: die Stadt, die Menschen und das Leben dort. Valjevo ist keine große Stadt, aber es gibt alles, was man braucht: Schulen, ein Krankenhaus, viele kleine Geschäfte und einen großen Markt. Am Wochenende treffen sich die Menschen in der Fußgängerzone, trinken Kaffee und unterhalten sich. Besonders schön ist die Natur. Rund um die Stadt gibt es grüne Hügel und einen Fluss, in dem ich als Kind oft geschwommen bin. Ein Vorteil ist, dass das Leben dort ruhig und nicht so teuer ist. Die Menschen kennen sich und helfen einander. Ein Nachteil ist, dass es wenig Arbeit gibt. Deshalb sind viele junge Leute ins Ausland gegangen, auch ich. Ich habe die Erfahrung gemacht, dass man seine Heimat nie ganz vergisst, obwohl man weit weg wohnt. Zusammenfassend kann ich sagen, dass Valjevo für mich der schönste Ort ist, weil dort meine Familie und meine besten Erinnerungen sind. Ich fahre jedes Jahr im Sommer hin. Vielen Dank, dass Sie zugehört haben. Haben Sie noch Fragen?","topicEn":"My home town"},{"topic":"Mein Beruf / meine Arbeit","text":"Ich möchte Ihnen meinen Beruf vorstellen. Ich arbeite als Verkäuferin in einem Supermarkt und bin seit vier Jahren in dieser Firma. Zuerst erzähle ich von meinem Arbeitstag, danach von den Vor- und Nachteilen und zum Schluss von meinen Plänen. Meine Arbeit beginnt um sieben Uhr morgens. Ich räume die Regale auf und kontrolliere, ob alle Waren frisch sind. Danach arbeite ich an der Kasse. Dort habe ich viel Kontakt mit Kunden, und das gefällt mir besonders gut. Manchmal muss ich auch Bestellungen machen oder beim Einräumen helfen. Ein Vorteil ist, dass ich nette Kollegen habe und jeden Tag etwas Neues passiert. Ein Nachteil ist, dass ich oft am Samstag arbeiten muss und dann wenig Zeit für meine Familie bleibt. Außerdem ist das Gehalt nicht sehr hoch. Ich habe die Erfahrung gemacht, dass man in diesem Beruf geduldig und freundlich sein muss. Wenn ein Kunde sich ärgert, darf ich nicht unhöflich werden. Deshalb möchte ich in zwei Jahren eine Weiterbildung machen, damit ich mehr verdienen kann. Zum Schluss möchte ich sagen, dass ich meine Arbeit gern mache, obwohl sie manchmal anstrengend ist. Vielen Dank für Ihre Aufmerksamkeit.","topicEn":"My job / my work"}],"watchOut":["Die Stichwörter nicht einfach vorlesen, sondern daraus ganze Sätze machen.","Nach drei Minuten ist die Präsentation zu Ende – die Zeit vorher zu Hause üben.","Keine langen, komplizierten Nebensätze bilden; kurze Hauptsätze sind verständlicher.","Die eigene Meinung oder Erfahrung nicht vergessen, sonst wirkt der Vortrag unpersönlich.","Zu leise sprechen und die Prüfer nicht anschauen – Augenkontakt gehört dazu."],"watchOutEn":["Do not simply read the keywords out — turn them into full sentences.","The presentation is over after three minutes — practise the timing at home beforehand.","Do not build long, complicated subordinate clauses; short main clauses are easier to understand.","Do not forget your own opinion or experience, otherwise the talk sounds impersonal.","Speaking too quietly and not looking at the examiners — eye contact is part of it."]}'::jsonb),
    ('speaking-guide', 'telc-deutsch-b1.speaking-guide.sp2', 1, 'part', 'Teil 2 – Diskussion', 'Part 2 – Discussion', 'Der Kandidat diskutiert etwa sechs Minuten mit seinem Partner über ein kontroverses Alltagsthema, äußert seine Meinung, begründet sie und reagiert auf den Partner.', 'The candidate discusses a controversial everyday topic with their partner for about six minutes, gives their opinion, justifies it and responds to the partner.', '{"minutes":6,"approach":[{"step":"Die eigene Position klar sagen","detail":"Sagen Sie am Anfang deutlich, was Sie denken. Ein Satz wie Ich bin der Meinung, dass ... reicht völlig aus.","seconds":50,"stepEn":"State your own position clearly","detailEn":"Say clearly at the start what you think. One sentence like Ich bin der Meinung, dass ... is quite enough."},{"step":"Die Meinung begründen","detail":"Nennen Sie mindestens einen Grund mit weil, denn oder deshalb. Ohne Begründung wirkt die Meinung leer.","seconds":60,"stepEn":"Justify your opinion","detailEn":"Give at least one reason with weil, denn or deshalb. Without a reason the opinion sounds empty."},{"step":"Ein Beispiel geben","detail":"Erzählen Sie eine kurze Situation aus Ihrem Leben oder aus Ihrem Umfeld. Das macht Ihr Argument konkret.","seconds":60,"stepEn":"Give an example","detailEn":"Tell a short story from your life or from the people around you. That makes your argument concrete."},{"step":"Auf den Partner reagieren","detail":"Hören Sie zu und gehen Sie auf sein Argument ein: stimmen Sie zu, widersprechen Sie höflich oder ergänzen Sie etwas.","seconds":70,"stepEn":"React to your partner","detailEn":"Listen and respond to their argument: agree, disagree politely or add something."},{"step":"Beide Seiten abwägen","detail":"Zeigen Sie, dass Sie auch die andere Meinung verstehen. Das wirkt reif und bringt das Gespräch voran.","seconds":70,"stepEn":"Weigh up both sides","detailEn":"Show that you understand the other opinion too. That sounds mature and moves the conversation forward."},{"step":"Zu einem Ergebnis kommen","detail":"Fassen Sie am Ende zusammen, wo Sie stehen. Eine Einigung ist gut, aber eine klare eigene Position ist wichtiger.","seconds":50,"stepEn":"Come to a conclusion","detailEn":"Sum up at the end where you stand. Reaching agreement is good, but a clear position of your own matters more."}],"phrases":[{"group":"Meinung äußern","hint":"Mit diesen Sätzen sagen Sie klar, was Sie zu dem Thema denken.","items":[{"de":"Ich bin der Meinung, dass ...","en":"I am of the opinion that ...","example":"Ich bin der Meinung, dass Handys in der Schule verboten sein sollten."},{"de":"Meiner Meinung nach ...","en":"In my opinion ...","example":"Meiner Meinung nach fahren zu viele Autos in der Innenstadt."},{"de":"Ich finde, dass ...","en":"I find that ...","example":"Ich finde, dass Kinder mehr draußen spielen sollten."},{"de":"Aus meiner Sicht ist es wichtig, dass ...","en":"From my point of view it is important that ...","example":"Aus meiner Sicht ist es wichtig, dass alle Schüler ein eigenes Frühstück bekommen."},{"de":"Ich persönlich glaube, dass ...","en":"I personally believe that ...","example":"Ich persönlich glaube, dass man ohne Handy heute nicht mehr arbeiten kann."},{"de":"Für mich ist klar, dass ...","en":"For me it is clear that ...","example":"Für mich ist klar, dass ein Auto in der Stadt oft nur teuer und langsam ist."}],"groupEn":"Expressing an opinion","hintEn":"With these sentences you say clearly what you think about the topic."},{"group":"Begründen","hint":"Diese Redemittel liefern den Grund für Ihre Meinung.","items":[{"de":"..., weil ...","en":"... because ...","example":"Ich bin gegen Handys im Unterricht, weil die Kinder dann nicht aufpassen."},{"de":"Der Grund dafür ist, dass ...","en":"The reason for that is that ...","example":"Der Grund dafür ist, dass die Luft in der Stadt sehr schlecht ist."},{"de":"Deshalb bin ich der Meinung, dass ...","en":"That is why I am of the opinion that ...","example":"Deshalb bin ich der Meinung, dass wir mehr Busse brauchen."},{"de":"..., denn ...","en":"... because ...","example":"Ein Handy ist im Notfall sehr praktisch, denn die Eltern können ihr Kind immer erreichen."},{"de":"Ein wichtiger Grund ist, dass ...","en":"An important reason is that ...","example":"Ein wichtiger Grund ist, dass die Kinder mit dem Handy auch lernen können."},{"de":"Dafür gibt es mehrere Gründe: Erstens ..., zweitens ...","en":"There are several reasons for that: firstly ..., secondly ...","example":"Dafür gibt es mehrere Gründe: Erstens ist es billiger, zweitens ist es besser für die Umwelt."}],"groupEn":"Giving reasons","hintEn":"These phrases supply the reason for your opinion."},{"group":"Beispiele geben","hint":"Mit diesen Sätzen machen Sie Ihr Argument konkret und lebendig.","items":[{"de":"Zum Beispiel ...","en":"For example ...","example":"Zum Beispiel sehe ich im Bus viele Jugendliche, die nur auf ihr Handy schauen."},{"de":"Ein gutes Beispiel dafür ist ...","en":"A good example of that is ...","example":"Ein gutes Beispiel dafür ist meine Nichte: Sie lernt mit dem Handy neue Wörter."},{"de":"Ich kenne jemanden, der ...","en":"I know someone who ...","example":"Ich kenne einen Kollegen, der jeden Tag mit dem Auto zur Arbeit fährt."},{"de":"Bei uns in ... ist es so, dass ...","en":"Where I come from in ..., it is the case that ...","example":"Bei uns in meinem Dorf ist es so, dass die Kinder erst ab zwölf ein Handy bekommen."},{"de":"Das sieht man zum Beispiel daran, dass ...","en":"You can see that, for example, from the fact that ...","example":"Das sieht man zum Beispiel daran, dass morgens alle Straßen voll sind."},{"de":"In meiner Kindheit war es so, dass ...","en":"In my childhood it was the case that ...","example":"In meiner Kindheit war es so, dass wir den ganzen Tag draußen gespielt haben."}],"groupEn":"Giving examples","hintEn":"With these sentences you make your argument concrete and vivid."},{"group":"Zustimmen","hint":"So zeigen Sie dem Partner, dass Sie sein Argument akzeptieren.","items":[{"de":"Da hast du recht.","en":"You are right about that.","example":"Da hast du recht, das habe ich auch schon erlebt."},{"de":"Das sehe ich genauso.","en":"I see it exactly the same way.","example":"Das sehe ich genauso, ein Verbot löst das Problem nicht."},{"de":"Ich stimme dir zu, weil ...","en":"I agree with you because ...","example":"Ich stimme dir zu, weil die Kinder ohne Handy sicherer sind."},{"de":"Das ist ein gutes Argument.","en":"That is a good argument.","example":"Das ist ein gutes Argument, daran habe ich noch nicht gedacht."},{"de":"Genau, das finde ich auch.","en":"Exactly, I think so too.","example":"Genau, das finde ich auch, und deshalb brauchen wir klare Regeln."},{"de":"Du hast recht, aber ich möchte noch etwas ergänzen.","en":"You are right, but I would like to add something.","example":"Du hast recht, aber ich möchte noch etwas ergänzen: Die Lehrer müssen auch mitmachen."}],"groupEn":"Agreeing","hintEn":"This is how you show your partner that you accept their argument."},{"group":"Widersprechen","hint":"Mit diesen Sätzen widersprechen Sie höflich, ohne den Partner anzugreifen.","items":[{"de":"Das sehe ich anders.","en":"I see that differently.","example":"Das sehe ich anders, denn ein Verbot kontrolliert niemand."},{"de":"Da bin ich anderer Meinung.","en":"I have a different opinion on that.","example":"Da bin ich anderer Meinung, weil viele Familien auf das Auto angewiesen sind."},{"de":"Ich verstehe dein Argument, aber ...","en":"I understand your argument, but ...","example":"Ich verstehe dein Argument, aber die Schule kann nicht alles verbieten."},{"de":"Das stimmt zwar, aber ...","en":"That is true, but ...","example":"Das stimmt zwar, aber ein Handy kann im Unterricht auch helfen."},{"de":"Ich bin nicht sicher, ob das stimmt.","en":"I am not sure whether that is true.","example":"Ich bin nicht sicher, ob das stimmt, denn viele Busse kommen zu spät."},{"de":"Im Gegenteil, ich finde, dass ...","en":"On the contrary, I think that ...","example":"Im Gegenteil, ich finde, dass ein Auto in der Stadt mehr Probleme macht."}],"groupEn":"Disagreeing","hintEn":"With these sentences you disagree politely without attacking your partner."},{"group":"Abwägen und abschließen","hint":"Diese Redemittel helfen Ihnen, beide Seiten zu sehen und das Gespräch zu beenden.","items":[{"de":"Einerseits ..., andererseits ...","en":"On the one hand ..., on the other hand ...","example":"Einerseits ist das Handy praktisch, andererseits stört es im Unterricht."},{"de":"Auf der einen Seite hat ... Vorteile, auf der anderen Seite ...","en":"On the one hand ... has advantages, on the other hand ...","example":"Auf der einen Seite hat das Auto Vorteile, auf der anderen Seite ist es teuer."},{"de":"Man muss beide Seiten sehen.","en":"One has to see both sides.","example":"Man muss beide Seiten sehen, denn es gibt gute Gründe für und gegen ein Verbot."},{"de":"Insgesamt denke ich, dass ...","en":"Overall I think that ...","example":"Insgesamt denke ich, dass klare Regeln besser sind als ein Verbot."},{"de":"Wir sind uns also einig, dass ...","en":"So we agree that ...","example":"Wir sind uns also einig, dass die Stadt mehr Radwege braucht."},{"de":"Ich kann beide Meinungen verstehen, aber ...","en":"I can understand both opinions, but ...","example":"Ich kann beide Meinungen verstehen, aber für mich ist die Umwelt wichtiger."}],"groupEn":"Weighing up and concluding","hintEn":"These phrases help you see both sides and bring the conversation to an end."}],"examples":[{"topic":"Handy in der Schule","text":"Ich bin der Meinung, dass Handys in der Schule nicht komplett verboten sein sollten. Meiner Meinung nach kommt es darauf an, wie die Schüler sie benutzen. In der Pause oder im Notfall ist ein Handy sehr praktisch, weil die Eltern ihre Kinder dann erreichen können. Allerdings stimme ich dir zu, dass Handys im Unterricht stören. Ich habe selbst die Erfahrung gemacht, dass viele Jugendliche nur auf den Bildschirm schauen und nicht aufpassen. Deshalb finde ich eine klare Regel besser als ein totales Verbot. Zum Beispiel müssen die Handys während der Stunde in der Tasche bleiben, und in der Pause darf man sie benutzen. Natürlich kann man sagen, dass ein Verbot einfacher zu kontrollieren ist. Das stimmt, aber ich glaube, dass die Schüler dann heimlich telefonieren. Besser ist es, wenn die Schule mit den Eltern zusammen Regeln aufstellt und den Kindern erklärt, warum ein vernünftiger Umgang wichtig ist. Ich kann beide Meinungen verstehen, aber insgesamt denke ich, dass ein Handy ein gutes Werkzeug sein kann, wenn man klare Grenzen setzt. Wir müssen also nicht verbieten, sondern erziehen.","topicEn":"Mobile phones in school"},{"topic":"Auto in der Stadt","text":"Ich bin der Meinung, dass es in der Innenstadt zu viele Autos gibt. Meiner Meinung nach sollte man den Autoverkehr in der Stadtmitte reduzieren, weil die Luft dort sehr schlecht ist und es oft laut ist. Ein wichtiger Grund dafür ist die Umwelt. Zum Beispiel sehe ich jeden Morgen vor der Schule eine lange Autoschlange, und die Kinder müssen zwischen den Autos über die Straße gehen. Das ist gefährlich. Außerdem brauchen die Autos viel Platz, deshalb gibt es in vielen Straßen keinen Radweg. Natürlich verstehe ich die Leute, die mit dem Auto zur Arbeit fahren. Da hast du recht, besonders wenn sie weit weg wohnen oder kleine Kinder haben. Ich verstehe auch, dass ein Bus nicht immer pünktlich kommt. Aber ich finde, dass die Stadt bessere Busse und sichere Radwege anbieten muss, damit die Menschen freiwillig umsteigen. Auf der einen Seite kostet das viel Geld, auf der anderen Seite wird das Leben in der Stadt dadurch ruhiger und gesünder. Insgesamt denke ich, dass wir alle etwas ändern müssen: weniger Auto, mehr Bus und Fahrrad.","topicEn":"Cars in the city"}],"watchOut":["Zu kurz antworten: Einwortantworten wie Ja oder Nein reichen in der Diskussion nicht.","Den Partner ständig unterbrechen und nicht ausreden lassen.","Nur die eigene Meinung wiederholen und nicht auf das Argument des Partners eingehen.","Zu komplizierte Sätze mit vielen Nebensätzen bilden – lieber klar und einfach bleiben.","Am Ende keine klare Position nennen, sondern das Gespräch einfach abbrechen."],"watchOutEn":["Answering too briefly: one-word answers like Ja or Nein are not enough in a discussion.","Constantly interrupting your partner and never letting them finish.","Only repeating your own opinion and never engaging with your partner’s argument.","Building overly complicated sentences with many subordinate clauses — stay clear and simple instead.","Not stating a clear position at the end, but simply breaking off the conversation."]}'::jsonb),
    ('speaking-guide', 'telc-deutsch-b1.speaking-guide.sp3', 2, 'part', 'Teil 3 – Gemeinsam etwas planen', 'Part 3 – Planning something together', 'Der Kandidat plant mit seinem Partner etwa fünf Minuten lang eine gemeinsame Aktivität, macht Vorschläge, reagiert auf Ideen und einigt sich am Ende auf ein konkretes Ergebnis.', 'The candidate plans a shared activity with their partner for about five minutes, makes suggestions, responds to ideas and agrees on a concrete result at the end.', '{"minutes":5,"approach":[{"step":"Begrüßen und einen ersten Vorschlag machen","detail":"Beginnen Sie das Gespräch und bringen Sie eine konkrete Idee ein. So führen Sie das Gespräch von Anfang an.","seconds":40,"stepEn":"Greet your partner and make a first suggestion","detailEn":"Start the conversation and put forward a concrete idea. That way you lead the conversation from the beginning."},{"step":"Nach der Meinung des Partners fragen","detail":"Fragen Sie nach seiner Meinung und lassen Sie ihn antworten. Ein Gespräch funktioniert nur mit zwei Personen.","seconds":50,"stepEn":"Ask for your partner’s opinion","detailEn":"Ask what they think and let them answer. A conversation only works with two people."},{"step":"Alternativen abwägen","detail":"Vergleichen Sie zwei Möglichkeiten mit ihren Vor- und Nachteilen, zum Beispiel Preis, Entfernung oder Wetter.","seconds":70,"stepEn":"Weigh up alternatives","detailEn":"Compare two options with their advantages and disadvantages, for example price, distance or weather."},{"step":"Aufgaben verteilen","detail":"Klären Sie, wer was macht. Sagen Sie klar, was Sie übernehmen, und fragen Sie den Partner nach seinen Aufgaben.","seconds":60,"stepEn":"Share out the tasks","detailEn":"Clarify who does what. Say clearly what you will take on and ask your partner about their tasks."},{"step":"Zeit und Ort festlegen","detail":"Nennen Sie einen konkreten Tag, eine Uhrzeit und einen Treffpunkt. Ohne diese Angaben bleibt die Planung unvollständig.","seconds":50,"stepEn":"Fix a time and a place","detailEn":"Name a concrete day, a time and a meeting point. Without these details the plan stays incomplete."},{"step":"Die Entscheidung bestätigen","detail":"Fassen Sie am Ende alle Punkte noch einmal zusammen und lassen Sie sich die Einigung bestätigen.","seconds":30,"stepEn":"Confirm the decision","detailEn":"Sum up all the points once more at the end and have the agreement confirmed."}],"phrases":[{"group":"Vorschläge machen","hint":"Mit diesen Sätzen bringen Sie eine erste Idee in das Gespräch ein.","items":[{"de":"Ich schlage vor, dass wir ...","en":"I suggest that we ...","example":"Ich schlage vor, dass wir ein Abschiedsfest im Garten feiern."},{"de":"Wie wäre es, wenn wir ...?","en":"How about we ...?","example":"Wie wäre es, wenn wir am Sonntag einen Ausflug machen?"},{"de":"Wir könnten ...","en":"We could ...","example":"Wir könnten auch ins Museum gehen, das ist nicht so teuer."},{"de":"Ich hätte eine Idee: ...","en":"I would have an idea: ...","example":"Ich hätte eine Idee: Wir treffen uns bei mir und kochen zusammen."},{"de":"Vielleicht können wir ...","en":"Maybe we can ...","example":"Vielleicht können wir die Fahrräder bei mir im Hof parken."},{"de":"Sollen wir ...?","en":"Shall we ...?","example":"Sollen wir zuerst die Getränke einkaufen?"}],"groupEn":"Making suggestions","hintEn":"With these sentences you bring a first idea into the conversation."},{"group":"Nach der Meinung fragen","hint":"Diese Fragen halten das Gespräch in Gang und beziehen den Partner ein.","items":[{"de":"Was hältst du davon?","en":"What do you think of that?","example":"Wir könnten am Samstag feiern. Was hältst du davon?"},{"de":"Wie findest du die Idee?","en":"How do you find the idea?","example":"Wir fahren mit dem Zug. Wie findest du die Idee?"},{"de":"Bist du damit einverstanden?","en":"Do you agree with that?","example":"Wir treffen uns um zehn Uhr am Bahnhof. Bist du damit einverstanden?"},{"de":"Was meinst du dazu?","en":"What do you think about that?","example":"Ich übernehme den Kuchen. Was meinst du dazu?"},{"de":"Hast du einen anderen Vorschlag?","en":"Do you have another suggestion?","example":"Der Park ist vielleicht zu weit. Hast du einen anderen Vorschlag?"},{"de":"Passt dir das?","en":"Does that suit you?","example":"Sonntag um elf Uhr im Café am Markt – passt dir das?"}],"groupEn":"Asking for an opinion","hintEn":"These questions keep the conversation going and involve your partner."},{"group":"Alternativen abwägen","hint":"Mit diesen Sätzen vergleichen Sie zwei Möglichkeiten, bevor Sie sich entscheiden.","items":[{"de":"Wir haben zwei Möglichkeiten: Entweder ... oder ...","en":"We have two options: either ... or ...","example":"Wir haben zwei Möglichkeiten: Entweder feiern wir im Klassenzimmer oder im Park."},{"de":"Das ist günstiger, aber ...","en":"That is cheaper, but ...","example":"Das Café am Bahnhof ist günstiger, aber dort ist es sehr laut."},{"de":"Ein Vorteil von ... ist, dass ...","en":"An advantage of ... is that ...","example":"Ein Vorteil vom Park ist, dass wir dort grillen können."},{"de":"Im Vergleich zu ... ist ... besser, weil ...","en":"Compared to ..., ... is better because ...","example":"Im Vergleich zum Auto ist der Zug besser, weil er billiger ist."},{"de":"Wenn wir ... machen, dann ...","en":"If we do ..., then ...","example":"Wenn wir früh losfahren, dann sind wir schon um zwölf da."},{"de":"Das Problem dabei ist, dass ...","en":"The problem with that is that ...","example":"Das Problem dabei ist, dass am Sonntag kein Bus fährt."}],"groupEn":"Weighing up alternatives","hintEn":"With these sentences you compare two options before deciding."},{"group":"Aufgaben verteilen","hint":"Diese Redemittel klären, wer sich um was kümmert.","items":[{"de":"Ich kann ... übernehmen.","en":"I can take care of ...","example":"Ich kann die Getränke und den Kuchen übernehmen."},{"de":"Kannst du bitte ...?","en":"Could you please ...?","example":"Kannst du bitte die Musikbox mitbringen?"},{"de":"Soll ich ... mitbringen?","en":"Shall I bring ...?","example":"Soll ich einen Salat und Brot mitbringen?"},{"de":"Wer kümmert sich um ...?","en":"Who will take care of ...?","example":"Wer kümmert sich um die Einladungen für die anderen?"},{"de":"Du kümmerst dich um ..., und ich mache ...","en":"You take care of ..., and I will do ...","example":"Du kümmerst dich um die Musik, und ich mache die Einladungen."},{"de":"Ich frage ..., ob er/sie helfen kann.","en":"I will ask ... whether he/she can help.","example":"Ich frage Marco, ob er seinen Grill mitbringen kann."}],"groupEn":"Sharing out tasks","hintEn":"These phrases clarify who takes care of what."},{"group":"Zustimmen und ablehnen","hint":"So reagieren Sie auf die Vorschläge Ihres Partners – freundlich, aber klar.","items":[{"de":"Das ist eine gute Idee.","en":"That is a good idea.","example":"Das ist eine gute Idee, dann müssen wir nichts kochen."},{"de":"Einverstanden.","en":"Agreed.","example":"Wir teilen die Kosten. Einverstanden."},{"de":"Das finde ich gut, machen wir so.","en":"I like that, let us do it that way.","example":"Wir fahren mit dem Fahrrad. Das finde ich gut, machen wir so."},{"de":"Das passt mir leider nicht, weil ...","en":"Unfortunately that does not suit me, because ...","example":"Samstagmorgen passt mir leider nicht, weil ich arbeiten muss."},{"de":"Lieber nicht, denn ...","en":"Rather not, because ...","example":"Lieber nicht im Restaurant, denn das wird zu teuer."},{"de":"Das ist mir zu ...","en":"That is too ... for me.","example":"Das ist mir zu teuer, wir haben nur hundert Euro zusammen."}],"groupEn":"Agreeing and declining","hintEn":"This is how you react to your partner’s suggestions — friendly but clear."},{"group":"Entscheidung festhalten","hint":"Mit diesen Sätzen beenden Sie die Planung mit einem klaren Ergebnis.","items":[{"de":"Also machen wir es so: ...","en":"So let us do it like this: ...","example":"Also machen wir es so: Wir treffen uns am Samstag um sechs Uhr im Park."},{"de":"Wir haben uns entschieden, dass ...","en":"We have decided that ...","example":"Wir haben uns entschieden, dass jeder etwas zu essen mitbringt."},{"de":"Dann treffen wir uns am ... um ... Uhr.","en":"Then we will meet on ... at ... o''clock.","example":"Dann treffen wir uns am Sonntag um zehn Uhr am Bahnhof."},{"de":"Ich notiere: ...","en":"Let me note down: ...","example":"Ich notiere: Sonntag, zehn Uhr, Bahnhof, Fahrradtour und Picknick."},{"de":"Sind wir uns also einig?","en":"So are we agreed?","example":"Wir machen die Fahrradtour und jeder bringt etwas mit. Sind wir uns also einig?"},{"de":"Super, dann ist alles klar. Ich freue mich schon.","en":"Great, then everything is clear. I am already looking forward to it.","example":"Super, dann ist alles klar. Ich freue mich schon auf unser Fest."}],"groupEn":"Recording the decision","hintEn":"With these sentences you end the planning with a clear result."}],"examples":[{"topic":"Ein Abschiedsfest planen","text":"Also, ich hätte eine Idee: Wir könnten für unseren Kurs ein Abschiedsfest machen. Was hältst du davon? Ich finde auch, dass wir das verdient haben. Wann sollen wir feiern? Am Samstagabend wäre gut, dann haben alle Zeit. Und wo? Wir haben zwei Möglichkeiten: Entweder feiern wir im Klassenzimmer oder im Park. Ein Vorteil vom Park ist, dass wir dort draußen sitzen und grillen können. Natürlich kann es regnen, aber dann gehen wir einfach ins Klassenzimmer. Was meinst du dazu? Gut, dann machen wir es so. Jetzt müssen wir noch die Aufgaben verteilen. Ich kann die Einladungen schreiben und den Kuchen besorgen. Kannst du bitte die Getränke mitbringen? Super, danke. Wer kümmert sich um die Musik? Vielleicht fragst du Marco, ob er seine Box mitbringt. Und die Fotos mache ich, ich habe eine gute Kamera. Also machen wir es so: Wir treffen uns am Samstag um achtzehn Uhr im Stadtpark. Ich schreibe die Einladungen, du bringst die Getränke mit, und Marco kommt mit der Musik. Sind wir uns also einig? Perfekt, dann ist alles klar. Ich freue mich schon auf unser Fest.","topicEn":"Planning a farewell party"},{"topic":"Einen Ausflug planen","text":"Wir sollen für unseren Deutschkurs einen Ausflug planen, deshalb hätte ich eine Idee: Wir könnten nach Heidelberg fahren, weil die Stadt schön ist und viele Museen hat. Was hältst du davon? Heidelberg ist allerdings etwas weit. Wie wäre es, wenn wir stattdessen in den Zoo gehen? Das ist billiger, und die Fahrt dauert nur eine Stunde. Das stimmt, aber im Zoo waren wir schon letztes Jahr. Wir könnten auch eine Fahrradtour am Fluss machen. Das kostet nichts und macht Spaß. Das finde ich gut, machen wir so. Wann passt es dir? Am Samstag oder lieber am Sonntag? Sonntag ist besser, weil ich am Samstag arbeiten muss. Wir müssen aber auch an das Wetter denken. Wenn es regnet, bleiben wir zu Hause und machen einen Filmabend. Jetzt zu den Aufgaben: Ich kann die Fahrräder reservieren und die Route planen. Kannst du bitte das Picknick vorbereiten? Danke, das ist nett. Soll ich eine Nachricht in die Gruppe schreiben, damit alle Bescheid wissen? Ja, gern. Also halten wir fest: Am Sonntag um zehn Uhr treffen wir uns am Bahnhof, wir machen eine Fahrradtour am Fluss, und jeder bringt etwas zu essen mit. Sind wir uns also einig? Super, dann ist alles klar.","topicEn":"Planning an outing"}],"watchOut":["Nur eigene Vorschläge machen und nie nach der Meinung des Partners fragen.","Am Ende keine Entscheidung treffen – es muss ein klares Ergebnis mit Zeit und Ort stehen.","Den Treffpunkt oder die Uhrzeit vergessen, dann ist die Planung unvollständig.","Zu lange bei einer einzigen Idee bleiben und die fünf Minuten nicht einteilen.","Unhöflich ablehnen, statt freundlich zu sagen: Das passt mir leider nicht, weil ..."],"watchOutEn":["Only making your own suggestions and never asking for your partner’s opinion.","Not reaching a decision at the end — there has to be a clear result with a time and a place.","Forgetting the meeting point or the time, which leaves the plan incomplete.","Staying on a single idea for too long and not dividing up the five minutes.","Rejecting something rudely instead of saying politely: Das passt mir leider nicht, weil ..."]}'::jsonb)
